arguments:
{"args":["-lc","{
openssl x509 -in /app/ssl/server.crt -noout -subject
openssl x509 -in /app/ssl/server.crt -noout -dates
openssl x509 -in /app/ssl/server.crt -noout -fingerprint -sha256
echo "Not Before (YYYY-MM-DD): $(openssl x509 -in /app/ssl/server.crt -noout -startdate | cut -d= -f2 | awk '{print $4"-"$1"-"$2}' | python3 -c "import sys,datetime; s=sys.stdin.read().strip(); months={'Jan':'01','Feb':'02','Mar':'03','Apr':'04','May':'05','Jun':'06','Jul':'07','Aug':'08','Sep':'09','Oct':'10','Nov':'11','Dec':'12'}; y,m,d=s.split('-'); print(f'{y}-{months[m]}-{int(d):02d}')")"
echo "Not After (YYYY-MM-DD): $(openssl x509 -in /app/ssl/server.crt -noout -enddate | cut -d= -f2 | awk '{print $4"-"$1"-"$2}' | python3 -c "import sys,datetime; s=sys.stdin.read().strip(); months={'Jan':'01','Feb':'02','Mar':'03','Apr':'04','May':'05','Jun':'06','Jul':'07','Aug':'08','Sep':'09','Oct':'10','Nov':'11','Dec':'12'}; y,m,d=s.split('-'); print(f'{y}-{months[m]}-{int(d):02d}')")"
} | tee /app/ssl/verification.txt
cat /app/ssl/verification.txt"],"command":"bash"}
